/* Urutan = urutan siklus tombol L.  [kode, nama asli bahasa, rtl?]
   Menambah bahasa: salin satu blok di I18N + satu baris di sini. */
const LANGS = [
  ['id', 'Indonesia'], ['en', 'English'], ['zh', '中文'], ['hi', 'हिन्दी'], ['es', 'Español'],
  ['ar', 'العربية', true], ['fr', 'Français'], ['bn', 'বাংলা'], ['pt', 'Português'], ['ru', 'Русский'],
  ['ja', '日本語'],
];
const LKEY = 'mobil3d_lang';
let LANG = (() => {
  try { const s = localStorage.getItem(LKEY); if (I18N[s]) return s; } catch (e) {}
  const n = (navigator.language || 'id').slice(0, 2).toLowerCase();
  return I18N[n] ? n : 'id';
})();
function tt(k, v) {                                                 // terjemahan + isi {placeholder}
  let s = I18N[LANG][k] ?? I18N.id[k] ?? k;
  if (v) for (const x in v) s = s.split('{' + x + '}').join(v[x]);
  return s;
}

