function makeGroundTexture() {
  const c = document.createElement('canvas'); c.width = c.height = 512;
  const g = c.getContext('2d');
  g.fillStyle = '#5d6b73'; g.fillRect(0, 0, 512, 512);
  g.fillStyle = '#656f77';
  for (let i = 0; i < 1800; i++) g.fillRect(Math.random()*512, Math.random()*512, 2, 2);
  g.strokeStyle = 'rgba(255,255,255,.5)'; g.lineWidth = 4; g.strokeRect(2, 2, 508, 508);
  g.strokeStyle = 'rgba(255,255,255,.12)'; g.lineWidth = 2;
  g.beginPath(); g.moveTo(256, 0); g.lineTo(256, 512); g.moveTo(0, 256); g.lineTo(512, 256); g.stroke();
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = renderer.capabilities.getMaxAnisotropy();
  return t;
}
const TILE = 10;
const gTex = makeGroundTexture();
gTex.repeat.set(ARENA_HALF * 2 / TILE, ARENA_HALF * 2 / TILE);

const arena = new THREE.Mesh(
  new THREE.PlaneGeometry(ARENA_HALF * 2, ARENA_HALF * 2),
  new THREE.MeshStandardMaterial({ map: gTex, roughness: 0.95 })
);
arena.rotation.x = -Math.PI / 2;
arena.receiveShadow = true;
scene.add(arena);

const grass = new THREE.Mesh(                     // rumput di luar arena, mengikuti mobil
  new THREE.PlaneGeometry(800, 800),
  new THREE.MeshStandardMaterial({ color: 0x6f8f5a, roughness: 1 })
);
grass.rotation.x = -Math.PI / 2;
grass.position.y = -0.05;
grass.receiveShadow = true;
scene.add(grass);

// Pohon hiasan di luar arena
{
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x6b4a2b, roughness: 1 });
  const leafMat  = new THREE.MeshStandardMaterial({ color: 0x3f8a46, roughness: .9 });
  const trunkGeo = new THREE.CylinderGeometry(.25, .35, 1, 8);
  const leafGeo  = new THREE.ConeGeometry(1.6, 1, 10);
  for (let i = 0; i < 260; i++) {
    const R = ARENA_HALF + 70;
    const x = (Math.random() * 2 - 1) * R, z = (Math.random() * 2 - 1) * R;
    if (Math.abs(x) < ARENA_HALF + 9 && Math.abs(z) < ARENA_HALF + 9) continue;
    const h = 2 + Math.random() * 2.5, g = new THREE.Group();
    const tr = new THREE.Mesh(trunkGeo, trunkMat); tr.scale.y = h; tr.position.y = h / 2;
    const lf = new THREE.Mesh(leafGeo, leafMat);  lf.scale.y = h * 1.6; lf.position.y = h * 1.3;
    tr.castShadow = lf.castShadow = true;
    g.add(tr, lf); g.position.set(x, 0, z); scene.add(g);
  }
}

/* =====================================================
   RINTANGAN & DINDING  (dengan tabrakan kotak berputar)
   ===================================================== */
const colliders = [];      // { x, z, w, d, rot, hw, hd, c, s, wall }
function addBox({ x, z, w, d, h = 3, rot = 0, color = 0xd9442f, wall = false }) {
  const mesh = new THREE.Mesh(
    new THREE.BoxGeometry(w, h, d),
    new THREE.MeshStandardMaterial({ color, roughness: .55, metalness: .1 })
  );
  mesh.position.set(x, h / 2, z);
  mesh.rotation.y = rot;
  mesh.castShadow = mesh.receiveShadow = true;
  mesh.add(new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry),
                                  new THREE.LineBasicMaterial({ color: wall ? 0x7d8a96 : 0x3a120b })));
  scene.add(mesh);
  colliders.push({ x, z, w, d, rot, hw: w / 2, hd: d / 2, c: Math.cos(rot), s: Math.sin(rot), wall });
}

// Dinding batas arena
{
  const L = ARENA_HALF * 2 + 8, T = 4, o = ARENA_HALF + T / 2;
  const wc = 0xe4eaf0;
  addBox({ x: 0, z:  o, w: L, d: T, h: 2.6, color: wc, wall: true });
  addBox({ x: 0, z: -o, w: L, d: T, h: 2.6, color: wc, wall: true });
  addBox({ x:  o, z: 0, w: T, d: L, h: 2.6, color: wc, wall: true });
  addBox({ x: -o, z: 0, w: T, d: L, h: 2.6, color: wc, wall: true });
}
