const dotTex = (() => {
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d'), r = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  r.addColorStop(0, 'rgba(255,255,255,1)'); r.addColorStop(.4, 'rgba(255,255,255,.6)'); r.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = r; g.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
})();

function makeParticles(max, size, additive, maxA) {               // kolam partikel: satu draw call, tanpa alokasi per frame
  const pos = new Float32Array(max * 3), col = new Float32Array(max * 4), vel = new Float32Array(max * 3);
  const life = new Float32Array(max), ttl = new Float32Array(max).fill(1);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.BufferAttribute(col, 4));
  const pts = new THREE.Points(g, new THREE.PointsMaterial({ size, map: dotTex, vertexColors: true, transparent: true,
    depthWrite: false, blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending }));
  pts.frustumCulled = false; scene.add(pts);
  let n = 0;
  return {
    emit(x, y, z, vx, vy, vz, r, gr, b, t) {
      const i = n, j = i * 3, k = i * 4; n = (n + 1) % max;
      pos[j] = x; pos[j + 1] = y; pos[j + 2] = z; vel[j] = vx; vel[j + 1] = vy; vel[j + 2] = vz;
      col[k] = r; col[k + 1] = gr; col[k + 2] = b; col[k + 3] = maxA; life[i] = ttl[i] = t;
    },
    update(dt, grav, drag) {
      const k = Math.max(0, 1 - drag * dt);
      for (let i = 0; i < max; i++) {
        if (life[i] <= 0) continue;
        life[i] -= dt; const j = i * 3;
        vel[j] *= k; vel[j + 1] = vel[j + 1] * k + grav * dt; vel[j + 2] *= k;
        pos[j] += vel[j] * dt; pos[j + 1] = Math.max(.05, pos[j + 1] + vel[j + 1] * dt); pos[j + 2] += vel[j + 2] * dt;
        col[i * 4 + 3] = life[i] > 0 ? maxA * life[i] / ttl[i] : 0;
      }
      g.attributes.position.needsUpdate = g.attributes.color.needsUpdate = true;
    },
    clear() { life.fill(0); for (let i = 0; i < max; i++) col[i * 4 + 3] = 0; g.attributes.color.needsUpdate = true; }
  };
}
const sparks = makeParticles(400, .6, true, 1), smoke = makeParticles(240, 1.1, false, .45);

function burst(x, y, z, cnt, c) {                                  // kilauan saat koin diambil / percikan tabrakan
  for (let i = 0; i < cnt; i++) {
    const a = Math.random() * 6.283, u = Math.random() * 2 - 1, q = Math.sqrt(1 - u * u), sp = 3 + Math.random() * 7;
    sparks.emit(x, y, z, Math.cos(a) * q * sp, (u * .6 + .5) * sp, Math.sin(a) * q * sp, c[0], c[1], c[2], .5 + Math.random() * .6);
  }
}
let exAcc = 0;
function exhaust(dt) {                                             // asap + api kecil di belakang mobil saat turbo
  exAcc += dt * 70;
  while (exAcc >= 1) {
    exAcc--;
    const side = Math.random() < .5 ? -.55 : .55;
    const x = car.position.x - fwd.x * 2.3 - fwd.z * side, z = car.position.z - fwd.z * 2.3 + fwd.x * side;
    smoke.emit(x, .45, z, -fwd.x * 3 + (Math.random() - .5) * 1.5, 1 + Math.random(), -fwd.z * 3 + (Math.random() - .5) * 1.5,
               .8, .8, .85, .7 + Math.random() * .5);
    if (Math.random() < .6) sparks.emit(x, .45, z, -fwd.x * 6 + (Math.random() - .5), .3 + Math.random(), -fwd.z * 6 + (Math.random() - .5),
               1, .55, .15, .22);
  }
}
function clearFX() { sparks.clear(); smoke.clear(); }

