const magRing = new THREE.Mesh(new THREE.RingGeometry(2.3, 2.6, 40),
  new THREE.MeshBasicMaterial({ color: 0x4da6ff, transparent: true, opacity: .6, depthWrite: false, side: THREE.DoubleSide }));
magRing.rotation.x = -Math.PI / 2; magRing.visible = false; scene.add(magRing);

/* ----- Rintangan: oil slick + batu ----- */
const OIL_COUNT = 10, ROCK_COUNT = 10, SPIN_TIME = 1.5;
const oils = [], rockMeshes = [];
const oilGeo = new THREE.CircleGeometry(1, 36), rockGeo = new THREE.DodecahedronGeometry(1, 0);
const oilMat = new THREE.MeshStandardMaterial({ color: 0x07070c, roughness: .12, metalness: .7, polygonOffset: true, polygonOffsetFactor: -2 });
const rockMat = new THREE.MeshStandardMaterial({ color: 0x7b8088, roughness: .9, flatShading: true });

function placeHazards() {
  oils.forEach(o => scene.remove(o.mesh)); oils.length = 0;
  rockMeshes.forEach(m => scene.remove(m)); rockMeshes.length = 0;
  for (let i = colliders.length - 1; i >= 0; i--) if (colliders[i].rock) colliders.splice(i, 1);
  const spots = [], R = ARENA_HALF - 8;
  const spot = gap => {
    for (let t = 0; t < 300; t++) {
      const x = (Math.random() * 2 - 1) * R, z = (Math.random() * 2 - 1) * R;
      if (Math.hypot(x, z) > 14 && colliders.every(b => distToBox(b, x, z) > 4) &&
          coins.every(c => Math.hypot(x - c.x, z - c.z) > 6) && spots.every(p => Math.hypot(x - p.x, z - p.z) > gap)) {
        spots.push({ x, z }); return { x, z };
      }
    }
    return null;
  };
  for (let i = 0; i < OIL_COUNT; i++) {
    const p = spot(12); if (!p) continue;
    const r = 2.6 + Math.random() * 1.6, mesh = new THREE.Mesh(oilGeo, oilMat);
    mesh.rotation.x = -Math.PI / 2; mesh.position.set(p.x, .03, p.z); mesh.scale.setScalar(r);
    scene.add(mesh); oils.push({ x: p.x, z: p.z, r, mesh });
  }
  for (let i = 0; i < ROCK_COUNT; i++) {
    const p = spot(8); if (!p) continue;
    const sz = 1.2 + Math.random() * .7, rot = Math.random() * 6.283, mesh = new THREE.Mesh(rockGeo, rockMat);
    mesh.scale.set(sz, sz * .75, sz); mesh.position.set(p.x, sz * .45, p.z); mesh.rotation.y = rot; mesh.castShadow = mesh.receiveShadow = true;
    scene.add(mesh); rockMeshes.push(mesh);
    const w = sz * 1.7;                                             // batu ikut tabrakan kotak yang sudah ada
    colliders.push({ x: p.x, z: p.z, w, d: w, rot, hw: w / 2, hd: w / 2, c: Math.cos(rot), s: Math.sin(rot), wall: false, rock: true });
  }
}
function hazardStep(dt) {                                          // lindas oli → spinout sementara
  oilCD -= dt;
  if (spinT > 0 || oilCD > 0 || Math.abs(speed) < 4) return;
  for (const o of oils) {
    if (Math.hypot(car.position.x - o.x, car.position.z - o.z) < o.r + .5) {
      spinT = SPIN_TIME; spinDir = Math.random() < .5 ? -1 : 1; oilCD = SPIN_TIME + 1.2;
      sfx.skid(); shake = Math.max(shake, .35); popText(tt('slip'), '#9aa6b2');
      break;
    }
  }
}
function magnetStep(dt) {                                          // tarik koin terdekat saat magnet aktif
  if (magnetT <= 0) return;
  magnetT = Math.max(0, magnetT - dt);
  for (const c of coins) {
    if (c.taken || c.type === 'magnet') continue;
    const dx = car.position.x - c.x, dz = car.position.z - c.z, d = Math.hypot(dx, dz);
    if (d > MAGNET_RANGE || d < .01) continue;
    const v = Math.min(1, (14 + (1 - d / MAGNET_RANGE) * 40) * dt / d);
    c.x += dx * v; c.z += dz * v; c.root.position.set(c.x, 0, c.z);
  }
}
function collect(c) {
  const col = c.type === 'time' ? [.3, 1, .45] : c.type === 'magnet' ? [.3, .65, 1] : [1, .82, .3];
  burst(c.x, 1.7, c.z, 30, col);
  if (c.type === 'time') { timeLeft += TIME_BONUS_COIN; sfx.time(); popText(tt('plus_time', { n: TIME_BONUS_COIN }), '#5dff8a'); }
  else if (c.type === 'magnet') { magnetT = MAGNET_TIME; sfx.magnet(); popText(tt('magnet_pop'), '#5cb8ff'); }
  else { got++; score += COIN_POINTS; SAVE.coins++; SAVE.total++; if (SAVE.total >= 100) unlock('coin'); save(); sfx.coin(); popText('+' + COIN_POINTS); }
  updateHUD();
}
function updateFX(dt, t) {
  updateSky(dt);
  sparks.update(dt, -7, 0); smoke.update(dt, .8, 1.5);
  magRing.visible = magnetT > 0;
  if (magnetT > 0) { magRing.position.set(car.position.x, .1, car.position.z); magRing.scale.setScalar(1 + .12 * Math.sin(t * 10)); }
}
/* ----- Waktu: pagi / siang / sore / malam (tekan T atau klik tombol) ----- */
const TOD = [
  { n: 'Pagi',  i: '🌅', sky: 0xf6c8a2, sun: 0xffd7a3, sunI: 1.1, hemi: .55, hSky: 0xffe2c8, hGnd: 0x4b5a3a, env: .6,  hl: 140, off: [-45, 22, 35], star: 0 },
  { n: 'Siang', i: '☀️', sky: 0xcfe7f7, sun: 0xfff1d6, sunI: 1.5, hemi: .5,  hSky: 0xdff0ff, hGnd: 0x4b5a3a, env: 1,   hl: 70,  off: [30, 50, 20],  star: 0 },
  { n: 'Sore',  i: '🌇', sky: 0xf0955a, sun: 0xff8a3d, sunI: 1.0, hemi: .4,  hSky: 0xffb98a, hGnd: 0x3a3a30, env: .45, hl: 220, off: [40, 16, -30], star: 0 },
  { n: 'Malam', i: '🌙', sky: 0x08102a, sun: 0x8fa8ff, sunI: .3,  hemi: .18, hSky: 0x3a4a8a, hGnd: 0x10141c, env: .07, hl: 520, off: [-25, 45, 20], star: 1 },
];
let todIdx = 1;
const sunOff = new THREE.Vector3(30, 50, 20), tmpC = new THREE.Color(), tmpV = new THREE.Vector3();
const sk = { sky: new THREE.Color(TOD[1].sky), sun: new THREE.Color(TOD[1].sun), hSky: new THREE.Color(TOD[1].hSky), hGnd: new THREE.Color(TOD[1].hGnd),
             sunI: TOD[1].sunI, hemi: TOD[1].hemi, env: TOD[1].env, hl: TOD[1].hl, star: 0 };
const starPos = new Float32Array(700 * 3);
for (let i = 0; i < 700; i++) {
  const a = Math.random() * 6.283, y = .08 + Math.random() * .92, q = Math.sqrt(1 - y * y);
  starPos.set([Math.cos(a) * q * 450, y * 450, Math.sin(a) * q * 450], i * 3);
}
const starGeo = new THREE.BufferGeometry(); starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0xffffff, size: 2, sizeAttenuation: false, transparent: true, opacity: 0, fog: false, depthWrite: false }));
stars.frustumCulled = false; stars.visible = false; scene.add(stars);

const todBtn = document.getElementById('todBtn');
function setTod(i) { todIdx = i; todBtn.textContent = TOD[i].i + ' ' + tt('tod' + i) + ' (T)'; }
function nextTime() { setTod((todIdx + 1) % TOD.length); }
todBtn.addEventListener('click', () => { todBtn.blur(); nextTime(); });
function updateSky(dt) {                                           // transisi halus menuju preset waktu
  const P = TOD[todIdx], k = 1 - Math.exp(-2.5 * dt), L = (a, b) => a + (b - a) * k;
  sk.sky.lerp(tmpC.set(P.sky), k); sk.sun.lerp(tmpC.set(P.sun), k);
  sk.hSky.lerp(tmpC.set(P.hSky), k); sk.hGnd.lerp(tmpC.set(P.hGnd), k);
  sk.sunI = L(sk.sunI, P.sunI); sk.hemi = L(sk.hemi, P.hemi); sk.env = L(sk.env, P.env); sk.hl = L(sk.hl, P.hl); sk.star = L(sk.star, P.star);
  sunOff.lerp(tmpV.set(P.off[0], P.off[1], P.off[2]), k);
  scene.background.copy(sk.sky); scene.fog.color.copy(sk.sky);
  sun.color.copy(sk.sun); sun.intensity = sk.sunI;
  hemi.color.copy(sk.hSky); hemi.groundColor.copy(sk.hGnd); hemi.intensity = sk.hemi;
  scene.environmentIntensity = sk.env;
  headlights.forEach(h => h.intensity = headlightsOn ? sk.hl : 0);
  stars.visible = sk.star > .02; stars.material.opacity = sk.star; stars.position.copy(camera.position);
}

/* ----- Suara mesin (sintesis: dua osilator + filter low-pass) ----- */
const engine = {};
function engineStart() {
  try {
    actx = actx || new (window.AudioContext || window.webkitAudioContext)();
    if (engine.g) return;
    const o1 = actx.createOscillator(), o2 = actx.createOscillator(), f = actx.createBiquadFilter(), g = actx.createGain();
    o1.type = 'sawtooth'; o2.type = 'square'; f.type = 'lowpass'; f.frequency.value = 500; g.gain.value = 0;
    o1.connect(f); o2.connect(f); f.connect(g); g.connect(actx.destination); o1.start(); o2.start();
    Object.assign(engine, { o1, o2, f, g });
  } catch (e) {}
}
function engineUpdate(throttle, boost) {
  if (!engine.g) return;
  const r = Math.min(Math.abs(speed) / MAX_SPEED, 1.5), t = actx.currentTime;
  const hz = 38 + r * 150 + (boost ? 25 : 0) + (throttle > 0 ? 10 : 0);
  engine.o1.frequency.setTargetAtTime(hz, t, .06); engine.o2.frequency.setTargetAtTime(hz * .5, t, .06);
  engine.f.frequency.setTargetAtTime(350 + r * 1400 + (throttle ? 300 : 0), t, .08);
  engine.g.gain.setTargetAtTime(state === 'playing' ? .03 + (throttle > 0 ? .03 : 0) + r * .03 : 0, t, .1);
}
/* ----- PROGRESI: simpan permanen, level, garasi, achievements ----- */
const SKEY = 'mobil3d_save', MAXLEVEL = 12, MAXUP = 5;
const SAVE = (() => {
  let d = {}; try { d = JSON.parse(localStorage.getItem(SKEY)) || {}; } catch (e) {}
  const v = { coins: 0, total: 0, hb: 0, level: 1, unlocked: 1, color: 'asli', ...d };
  v.up = { spd: 0, acc: 0, hnd: 0, ...(d.up || {}) }; v.owned = d.owned || ['asli']; v.ach = d.ach || {};
  return v;
})();
function save() { try { localStorage.setItem(SKEY, JSON.stringify(SAVE)); } catch (e) {} }
addEventListener('pagehide', save);
let curLevel = Math.min(SAVE.level, SAVE.unlocked), doneLevel = 1, lastReward = 0, lastKind = 'menu', curSub = null;
const levelInfo = L => ({ coins: Math.min(5 + L - 1, 12), time: Math.max(50, 95 - 5 * (L - 1)) });   // makin tinggi: koin ↑, waktu ↓
function applyLevel(L) { const i = levelInfo(L); COIN_COUNT = i.coins; GAME_TIME = i.time; }
function applyStats() {                                            // upgrade benar-benar mengubah fisika mobil
  MAX_SPEED = 56 * (1 + .07 * SAVE.up.spd); ACCEL = 12 * (1 + .12 * SAVE.up.acc); TURN_RATE = 1.4 * (1 + .07 * SAVE.up.hnd);
}
function levelWon() {
  doneLevel = curLevel; lastReward = 10 + 5 * curLevel; SAVE.coins += lastReward;
  curLevel = Math.min(curLevel + 1, MAXLEVEL); SAVE.unlocked = Math.max(SAVE.unlocked, curLevel); SAVE.level = curLevel;
}
const COLORS = [
  { id: 'asli', n: 'Asli', c: '#ffffff', p: 0 }, { id: 'merah', n: 'Merah', c: '#ff3b30', p: 25 }, { id: 'biru', n: 'Biru', c: '#2f7bff', p: 25 },
  { id: 'hijau', n: 'Hijau', c: '#22c55e', p: 30 }, { id: 'kuning', n: 'Kuning', c: '#ffd60a', p: 30 }, { id: 'oranye', n: 'Oranye', c: '#ff8a1f', p: 35 },
  { id: 'ungu', n: 'Ungu', c: '#a855f7', p: 40 }, { id: 'pink', n: 'Pink', c: '#ff5fa2', p: 40 }];
const UPS = [{ k: 'spd', n: 'Top Speed', i: '🏁', d: '+7% kecepatan maksimum per level' },
             { k: 'acc', n: 'Akselerasi', i: '⚡', d: '+12% percepatan per level' },
             { k: 'hnd', n: 'Handling', i: '🎯', d: '+7% daya belok per level' }];
